action.code:
int err;
if (lfs->block_count == 0) {
    return LFS_ERR_NOSPC;
}

for (lfs_block_t i = 0; i < lfs->block_count; ++i) {
    err = lfs_bd_erase(lfs, i);
    if (err == 0) {
        *block = i;
        return 0;
    } else if (err == LFS_ERR_CORRUPT) {
        /* Bad block, skip it */
        continue;
    } else {
        /* Propagate any other I/O error */
        return err;
    }
}

return LFS_ERR_NOSPC;

